def carry_over_pending_requests(apps, schema_editor):
    """Requests that were waiting before this change: the front desk still has to answer, the
    stylist (if the customer chose one) is asked now, and everyone gets a fresh 24 hours."""
    from datetime import timedelta

    from django.utils import timezone

    Appointment = apps.get_model("scheduling", "Appointment")
    deadline = timezone.now() + timedelta(hours=24)
    for appt in Appointment.objects.filter(status="requested"):
        appt.reception_status = "pending"
        appt.approval_expires_at = min(deadline, appt.preferred_start - timedelta(minutes=10))
        if appt.preferred_stylist_id:
            appt.stylist_status = "pending"
            appt.hold_stylist_id = appt.preferred_stylist_id
            appt.hold_start = appt.preferred_start
            appt.hold_end = appt.preferred_start + timedelta(minutes=appt.duration_minutes)
        appt.save(
            update_fields=[
                "reception_status",
                "stylist_status",
                "approval_expires_at",
                "hold_stylist",
                "hold_start",
                "hold_end",
            ]
        )


